/** One chapter as the JSON file the app imports — one verse per line, so a reader can find a verse by line. */
export function gitaChapterJson(verses: ReadonlyArray<GitaVerse>): string {
  return '[\n' + verses.map((v) => '  ' + JSON.stringify(v)).join(',\n') + '\n]\n';
}

/** The eighteen chapter files, keyed by their path in the app. */
export function gitaChapterFiles(): Record<string, string> {
  const out: Record<string, string> = {};
  GITA_CHAPTERS.forEach((verses, i) => { out['src/gita/' + String(i + 1).padStart(2, '0') + '.json'] = gitaChapterJson(verses); });
  return out;
}
